// Package pycompat reproduces the few Python behaviours the worker's output
// depends on, so the Go worker writes byte-for-byte the same data as the
// Python worker:
//
//   - FormatFloat  == repr(float)   (history entries "item:wr:ts", stats values)
//   - ParseInt     == int(str)      (user_id, item_id; error text goes to the DLQ)
//   - ParseFloat   == float(str)    (watch_ratio, ts, produced_ms)
//   - QuoteString  == repr(str)     (DLQ reasons quote the bad value)
//
// The expected outputs are generated by Python itself (scripts/gen_go_golden.py)
// and checked in testdata/pycompat_golden.json, so the two never drift apart.
package pycompat

import (
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// FormatFloat returns Python's repr(f): the shortest string that round-trips,
// in fixed notation when the decimal exponent is in [-4, 16), otherwise in
// scientific notation with at least two exponent digits. Whole numbers keep
// a trailing ".0" (repr(12.0) == "12.0", while Go's %g would print "12").
func FormatFloat(f float64) string {
	switch {
	case math.IsNaN(f):
		return "nan"
	case math.IsInf(f, 1):
		return "inf"
	case math.IsInf(f, -1):
		return "-inf"
	}
	// 'e' with precision -1 gives the shortest round-trip digits, e.g. "-1.2345e+03".
	s := strconv.FormatFloat(f, 'e', -1, 64)
	sign := ""
	if s[0] == '-' {
		sign, s = "-", s[1:]
	}
	mant, expStr, _ := strings.Cut(s, "e")
	exp, _ := strconv.Atoi(expStr)
	digits := strings.Replace(mant, ".", "", 1) // "12345" means 1.2345 * 10^exp

	if exp >= -4 && exp < 16 {
		var out string
		switch {
		case exp < 0: // 0.000ddd
			out = "0." + strings.Repeat("0", -exp-1) + digits
		case exp+1 >= len(digits): // integer value: pad with zeros, add ".0"
			out = digits + strings.Repeat("0", exp+1-len(digits)) + ".0"
		default:
			out = digits[:exp+1] + "." + digits[exp+1:]
		}
		return sign + out
	}
	mantissa := digits[:1]
	if len(digits) > 1 {
		mantissa += "." + digits[1:]
	}
	expSign := "+"
	if exp < 0 {
		expSign, exp = "-", -exp
	}
	return fmt.Sprintf("%s%se%s%02d", sign, mantissa, expSign, exp)
}

// QuoteString returns Python's repr(s) for a valid UTF-8 string.
func QuoteString(s string) string {
	quote := '\''
	if strings.ContainsRune(s, '\'') && !strings.ContainsRune(s, '"') {
		quote = '"'
	}
	var b strings.Builder
	b.WriteRune(quote)
	for _, r := range s {
		switch {
		case r == quote || r == '\\':
			b.WriteRune('\\')
			b.WriteRune(r)
		case r == '\t':
			b.WriteString(`\t`)
		case r == '\n':
			b.WriteString(`\n`)
		case r == '\r':
			b.WriteString(`\r`)
		case r < ' ' || r == 0x7f:
			fmt.Fprintf(&b, `\x%02x`, r)
		case r < 0x7f:
			b.WriteRune(r)
		case inRanges(pyPrintable, r): // CPython's str.isprintable() table
			b.WriteRune(r)
		case r <= 0xff:
			fmt.Fprintf(&b, `\x%02x`, r)
		case r <= 0xffff:
			fmt.Fprintf(&b, `\u%04x`, r)
		default:
			fmt.Fprintf(&b, `\U%08x`, r)
		}
	}
	b.WriteRune(quote)
	return b.String()
}

// ErrOutOfRange marks an integer that Python accepts (it has big ints) but
// that does not fit an int64. The worker treats it as a poison event.
var ErrOutOfRange = errors.New("out of range")

// ParseInt behaves like Python's int(s) for base 10: surrounding whitespace,
// a sign, "_" between digits and non-ASCII decimal digits (e.g. Arabic-Indic)
// are accepted. The error text matches Python's ValueError message.
func ParseInt(s string) (int64, error) {
	bad := fmt.Errorf("invalid literal for int() with base 10: %s", QuoteString(s))
	t, ok := toASCII(s)
	if !ok {
		return 0, bad
	}
	t = strings.Trim(t, asciiSpace)
	neg := false
	if t != "" && (t[0] == '+' || t[0] == '-') {
		neg, t = t[0] == '-', t[1:]
	}
	digits, ok := stripUnderscores(t)
	if !ok || digits == "" {
		return 0, bad
	}
	if neg {
		digits = "-" + digits
	}
	n, err := strconv.ParseInt(digits, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("int %s does not fit in int64: %w", digits, ErrOutOfRange)
	}
	return n, nil
}

// ParseFloat behaves like Python's float(s) for a str argument.
func ParseFloat(s string) (float64, error) {
	bad := fmt.Errorf("could not convert string to float: %s", QuoteString(s))
	t, ok := toASCII(s)
	if !ok {
		return 0, bad
	}
	t = strings.Trim(t, asciiSpace)
	body, sign := t, 1.0
	if body != "" && (body[0] == '+' || body[0] == '-') {
		if body[0] == '-' {
			sign = -1
		}
		body = body[1:]
	}
	switch strings.ToLower(body) {
	case "inf", "infinity":
		return math.Inf(int(sign)), nil
	case "nan":
		return math.NaN(), nil
	}
	if !isDecimalLiteral(body) {
		return 0, bad
	}
	f, err := strconv.ParseFloat(strings.ReplaceAll(body, "_", ""), 64)
	if err != nil && !errors.Is(err, strconv.ErrRange) { // Python overflows to inf, Go reports ErrRange
		return 0, bad
	}
	return sign * f, nil
}

const asciiSpace = " \t\n\v\f\r"

// toASCII mirrors CPython's _PyUnicode_TransformDecimalAndSpaceToASCII:
// non-ASCII whitespace becomes ' ', non-ASCII decimal digits become '0'-'9',
// anything else non-ASCII makes the number invalid.
func toASCII(s string) (string, bool) {
	if !utf8.ValidString(s) {
		return "", false
	}
	var b strings.Builder
	for _, r := range s {
		switch {
		case r < utf8.RuneSelf:
			b.WriteByte(byte(r))
		case unicode.IsSpace(r):
			b.WriteByte(' ')
		default:
			d, ok := decimalValue(r)
			if !ok {
				return "", false
			}
			b.WriteByte(byte('0' + d))
		}
	}
	return b.String(), true
}

// decimalValue returns the value of a non-ASCII decimal digit (str.isdecimal()).
// Each run in the table is made of complete 0..9 blocks, so the value is the
// offset from the start of the run modulo 10.
func decimalValue(r rune) (int, bool) {
	i := findRange(pyDecimal, r)
	if i < 0 {
		return 0, false
	}
	return int(r-pyDecimal[i].lo) % 10, true
}

// runeRange is an inclusive range of code points.
type runeRange struct{ lo, hi rune }

// findRange binary-searches sorted, non-overlapping ranges; -1 if r is in none.
func findRange(ranges []runeRange, r rune) int {
	i := sort.Search(len(ranges), func(i int) bool { return ranges[i].hi >= r })
	if i < len(ranges) && ranges[i].lo <= r {
		return i
	}
	return -1
}

func inRanges(ranges []runeRange, r rune) bool { return findRange(ranges, r) >= 0 }

// stripUnderscores accepts "1_000" (single underscores between digits only)
// and returns "1000"; it rejects "_1", "1_", "1__0" and any non-digit.
func stripUnderscores(s string) (string, bool) {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= '0' && c <= '9':
			b.WriteByte(c)
		case c == '_' && i > 0 && i+1 < len(s) && isDigit(s[i-1]) && isDigit(s[i+1]):
			// allowed separator
		default:
			return "", false
		}
	}
	return b.String(), true
}

// isDecimalLiteral checks Python's float grammar (no sign, no inf/nan):
// digits ["." [digits]] [exponent] | "." digits [exponent], where digits may
// contain single underscores between digits.
func isDecimalLiteral(s string) bool {
	mant, exp := s, ""
	if i := strings.IndexAny(s, "eE"); i >= 0 {
		mant, exp = s[:i], s[i+1:]
		if exp != "" && (exp[0] == '+' || exp[0] == '-') {
			exp = exp[1:]
		}
		if !isDigitPart(exp) {
			return false
		}
	}
	intPart, frac, hasDot := strings.Cut(mant, ".")
	if !hasDot {
		return isDigitPart(intPart)
	}
	if intPart == "" {
		return isDigitPart(frac)
	}
	return isDigitPart(intPart) && (frac == "" || isDigitPart(frac))
}

func isDigitPart(s string) bool {
	if s == "" {
		return false
	}
	_, ok := stripUnderscores(s)
	return ok
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }
